package com.lexorion.payroll.tenant;import org.springframework.beans.factory.annotation.Value;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.http.HttpHeaders;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;@Component public class PlatformPayrollAuthorityClient implements PayrollAuthorityClient{private final RestClient client;public PlatformPayrollAuthorityClient(@Qualifier("serviceRestClientBuilder") RestClient.Builder builder,@Value("${lexorion.platform-service-url}")String url){client=builder.baseUrl(url).build();}public TrustedPayrollContext validate(String key,String token,String host,String slug){return client.get().uri("/internal/payroll/workspaces/{key}/context",key).header(HttpHeaders.AUTHORIZATION,token).header(HttpHeaders.HOST,host).headers(h->{if(slug!=null)h.set("X-Lexorion-Organization",slug);}).retrieve().body(TrustedPayrollContext.class);}}
